// Normaliza la petición y decide la ruta. Nunca lanza errores: si algo está mal
// responde {success:false, message} para que la página pueda mostrarlo.
const FRONTEND_URL = 'http://localhost:3000'; // cámbialo cuando tengas dominio
const b = $json.body ?? $json;
const txt = (v, max) => String(v ?? '').trim().slice(0, max);
const fecha = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? '')) ? String(v) : '';

const publicas = ['register', 'login', 'forgot', 'reset_password'];
const privadas = ['me', 'logout', 'mis_tickets', 'detalle_ticket', 'cola_tecnico', 'cerrar_ticket',
                  'dashboard', 'tickets_admin', 'asignar_tecnico'];
const accion = txt(b.accion ?? b.action, 40).toLowerCase();

const d = {
  accion,
  session_token: txt(b.session_token, 200),
  email: txt(b.email ?? b.correo, 254).toLowerCase(),
  password: String(b.password ?? '').slice(0, 200),
  nombre: txt(b.name ?? b.nombre_completo ?? b.nombre, 150),
  identificacion: txt(b.cedula ?? b.identificacion, 50),
  telefono: txt(b.phone ?? b.telefono, 30),
  reset_token: txt(b.reset_token ?? b.token, 200),
  new_password: String(b.new_password ?? '').slice(0, 200),
  ticket_id: Number.parseInt(b.ticket_id, 10) || 0,
  tecnico_id: Number.parseInt(b.tecnico_id, 10) || 0,
  fecha_inicio: txt(b.fecha_inicio, 40),
  url_acta: txt(b.url_acta, 1000),
  resultado: txt(b.resultado, 4000),
  estado: txt(b.estado, 30),
  desde: fecha(b.desde),
  hasta: fecha(b.hasta),
  frontend_url: FRONTEND_URL,
};

const correoOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email);
const claveOk = (p) => p.length >= 10 && Buffer.byteLength(p, 'utf8') <= 72;
let error = '';
let status = 'invalid';
if (![...publicas, ...privadas].includes(accion)) error = 'Acción no válida.';
else if (['register', 'login', 'forgot'].includes(accion) && !correoOk) error = 'Escribe un correo electrónico válido.';
else if (accion === 'register' && d.nombre.length < 2) error = 'Escribe tu nombre completo.';
else if (accion === 'register' && !claveOk(d.password)) error = 'La contraseña debe tener al menos 10 caracteres.';
else if (accion === 'login' && !d.password) error = 'Escribe tu contraseña.';
else if (accion === 'reset_password' && !/^[0-9a-f]{64}$/.test(d.reset_token)) error = 'El enlace de recuperación no es válido.';
else if (accion === 'reset_password' && !claveOk(d.new_password)) error = 'La nueva contraseña debe tener al menos 10 caracteres.';
else if (privadas.includes(accion) && !d.session_token) { error = 'Inicia sesión para continuar.'; status = 'unauthorized'; }
else if (['detalle_ticket', 'cerrar_ticket', 'asignar_tecnico'].includes(accion) && d.ticket_id < 1) error = 'Número de ticket inválido.';
else if (accion === 'cerrar_ticket' && !/^https?:\/\/\S+\.pdf$/i.test(d.url_acta)) error = 'Adjunta el acta en PDF antes de cerrar el ticket.';
else if (accion === 'cerrar_ticket' && d.resultado.length < 5) error = 'Describe el resultado del servicio (mínimo 5 caracteres).';
else if (accion === 'asignar_tecnico' && d.tecnico_id < 1) error = 'Selecciona un técnico.';
else if (accion === 'asignar_tecnico' && Number.isNaN(Date.parse(d.fecha_inicio))) error = 'Selecciona la fecha y hora de la visita.';

if (accion === 'asignar_tecnico' && !error) d.fecha_inicio = new Date(d.fecha_inicio).toISOString();
const ruta = error ? 'invalido' : (publicas.includes(accion) ? accion : 'sesion');
return [{ json: { ...d, ruta, error, status } }];

const req = $('Validar acción de portal').first().json;
const s = $input.first().json;
const TODOS = ['cliente', 'tecnico', 'admin'];
const permisos = {
  me: TODOS, logout: TODOS, mis_tickets: TODOS, detalle_ticket: TODOS,
  cola_tecnico: ['tecnico'], cerrar_ticket: ['tecnico'],
  dashboard: ['admin'], tickets_admin: ['admin'], asignar_tecnico: ['admin'],
};
let ruta = req.accion, status = 'ok', message = '';
if (!s.usuario_id) {
  ruta = 'denegado'; status = 'unauthorized'; message = 'Tu sesión expiró o no es válida. Inicia sesión nuevamente.';
} else if (!(permisos[req.accion] || []).includes(s.rol)) {
  ruta = 'denegado'; status = 'forbidden'; message = 'Tu cuenta no tiene permiso para esta acción.';
} else if (['cola_tecnico', 'cerrar_ticket'].includes(req.accion) && !s.tecnico_id) {
  ruta = 'denegado'; status = 'forbidden'; message = 'Tu usuario técnico no está activo en la tabla de técnicos.';
}
return [{ json: { ...req, password: '', new_password: '', ruta, status, message,
  auth_usuario_id: Number(s.usuario_id || 0), auth_nombre: s.nombre_completo || '', auth_correo: s.correo || '',
  auth_rol: s.rol || '', auth_tecnico_id: Number(s.tecnico_id || 0) } }];

const x = $input.first().json;
if (!x.ticket_id) {
  return [{ json: { enviar: false, respuesta: { success: false, status: 'assignment_rejected',
    message: 'No se pudo asignar: revisa que el ticket esté pendiente, que la fecha sea futura y que el técnico no tenga otra cita a esa hora.' } } }];
}
const fecha_local = new Date(x.fecha_visita).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
return [{ json: { ...x, fecha_local, enviar: true, respuesta: { success: true, status: 'appointment_scheduled',
  ticket_id: x.ticket_id, fecha_visita: x.fecha_visita, tecnico_nombre: x.tecnico_nombre,
  message: `Visita asignada a ${x.tecnico_nombre} para el ${fecha_local} (hora Colombia)` } } }];
